119	/****************************************************************************
120	 * Name: beken_erase
121	 *
122	 * Description:
123	 *   Erase several blocks, each of the size previously reported.
124	 *
125	 ****************************************************************************/
126	
127	static int beken_erase(FAR struct mtd_dev_s *dev, off_t startblock,
128	                      size_t nblocks)
129	{
130	  FAR struct beken_dev_s *priv = (FAR struct beken_dev_s *)dev;
131	  uint32_t offset = startblock * MTD_ERASE_SIZE;
132	
133	  /* The interface definition assumes that all erase blocks are the same
134	   * size. If that is not true for this particular device, then transform
135	   * the start block and nblocks as necessary.
136	   */
137	
138	  /* Erase the specified blocks and return status (OK or a negated errno) */
139	  if (!priv->initialized)
140	    {
141	      return -EINVAL;
142	    }
143	  nxmutex_lock(&g_lock);
144	
145	  bk_flash_set_protect_type(FLASH_PROTECT_NONE);
146	
147	  for (int i=0; i<nblocks; i++)
148	    {
149	      bk_flash_erase_sector(offset + i * MTD_ERASE_SIZE);
150	    }
151	
152	  bk_flash_set_protect_type(FLASH_UNPROTECT_LAST_BLOCK);
153	
154	  nxmutex_unlock(&g_lock);
155	
156	  return nblocks;
157	}
