166	
167	static ssize_t beken_bread(FAR struct mtd_dev_s *dev, off_t startblock,
168	                          size_t nblocks, FAR uint8_t *buf)
169	{
170	  ssize_t ret;
171	  FAR struct beken_dev_s *priv = (FAR struct beken_dev_s *)dev;
172	  uint32_t offset = startblock * MTD_BLK_SIZE;
173	  uint32_t nbytes = nblocks * MTD_BLK_SIZE;
174	
175	  /* The interface definition assumes that all read/write blocks are the
176	   * same size.  If that is not true for this particular device, then
177	   * transform the start block and nblocks as necessary.
178	   */
179	
180	  /* Read the specified blocks into the provided user buffer and return
181	   * status (The positive, number of blocks actually read or a negated
182	   * errno).
183	   */
184	  if (!priv->initialized)
185	    {
186	      return -EINVAL;
187	    }
188	  nxmutex_lock(&g_lock);
189	
190	  ret = bk_flash_read_bytes(offset, buf, nbytes);
191	  if (ret == OK)
192	    {
193	      ret = nblocks;
194	    }
195	  nxmutex_unlock(&g_lock);
196	
197	  return ret;
198	}
