324	/****************************************************************************
325	 * Name: beken_ioctl
326	 ****************************************************************************/
327	
328	static int beken_ioctl(FAR struct mtd_dev_s *dev, int cmd, unsigned long arg)
329	{
330	  FAR struct beken_dev_s *priv = (FAR struct beken_dev_s *)dev;
331	  int ret = -EINVAL; /* Assume good command with bad parameters */
332	
333	  if (!priv->initialized)
334	    {
335	      return -EINVAL;
336	    }
337	
338	  switch (cmd)
339	    {
340	      case MTDIOC_GEOMETRY:
341	        {
342	          FAR struct mtd_geometry_s *geo = (FAR struct mtd_geometry_s *)arg;
343	          if (geo)
344	            {
345	              memset(geo, 0, sizeof(*geo));
346	
347	              /* Populate the geometry structure with information needed to
348	               * know the capacity and how to access the device.
349	               *
350	               * NOTE:
351	               * that the device is treated as though it where just an array
352	               * of fixed size blocks. That is most likely not true, but the
353	               * client will expect the device logic to do whatever is
354	               * necessary to make it appear so.
355	               */
356	
357	              geo->blocksize    = MTD_BLK_SIZE;              /* Size of one read/write block */
358	              geo->erasesize    = MTD_ERASE_SIZE;            /* Size of one erase block */
359	              geo->neraseblocks = FLASH_SIZE/MTD_ERASE_SIZE; /* Number of erase blocks */
360	              ret               = OK;
361	          }
362	        }
363	        break;
364	
365	      case BIOC_PARTINFO:
366	        {
367	          FAR struct partition_info_s *info =
368	            (FAR struct partition_info_s *)arg;
369	          if (info != NULL)
370	            {
371	              info->numsectors  = FLASH_SIZE/MTD_BLK_SIZE;
372	              info->sectorsize  = MTD_BLK_SIZE;
373	              info->startsector = 0;
374	              info->parent[0]   = '\0';
375	              ret               = OK;
376	            }
377	        }
378	        break;
379	
380	      case BIOC_XIPBASE:
381	        {
382	          /* Since the code blocks have additional crc section which is also
383	           * taken into account of calculating hash value, so it is not
384	           * appropriate to access it directly by the base address,
385	           * and simply return -ENOTTY here.
386	           */
387	          ret = -ENOTTY;
388	        }
389	        break;
390	
391	      case MTDIOC_BULKERASE:
392	        {
393	          /* Erase the entire device */
394	
395	          ret = OK;
396	        }
397	        break;
398	
399	      case MTDIOC_ERASESTATE:
400	        {
401	          uint8_t *result = (uint8_t *)arg;
402	          *result = MTD_ERASED_STATE;
403	
404	          ret = OK;
405	        }
406	        break;
407	
408	      default:
409	        ret = -ENOTTY; /* Bad command */
410	        break;
411	    }
412	
413	  return ret;
414	}
