185	
186	    uart_puts("u_bootloader enter\r\n");
187	
188	    /* --- WDT (product-grade): arm both APB + AON watchdogs (~8 s timeout).
189	     * Mirrors vendor bootloader sub_2000FE4: SYS_CTRL config + key unlock.
190	     * If boot_clock_cold_init or app validation hangs, WDT resets the chip.
191	     */
192	
193	    boot_wdt_init();
194	    boot_wdt_feed();
195	
196	    /* --- Cold-start DPLL enable + SPI recalibration.
197	     * On cold reset the BootROM leaves EN_DPLL=0; boot_clock_cold_init()
198	     * mirrors the Armino SDK sys_hal_early_init analog-register sequence.
199	     * If any analog-SPI write times out (ANA_SPI_TIMEOUT), the function
200	     * returns early and the app sees DPLL off.
201	     *
202	     * Retry up to 3 times: SPI timeouts can be transient (power-on noise).
203	     * Worst-case time: ~100 ms per attempt × 3 = 300 ms << 8 s WDT.
204	     */
205	
206	    for (retry = 0; retry < 3; retry++) {
207	        boot_wdt_feed();
208	        boot_clock_cold_init();
209	
210	        /* Check DPLL enable (ANA_REG5 bit5).  If set, cold-init succeeded. */
211	        if (REG32(0x44010114u) & (1u << 5)) {
212	            cold_ok = 1;
213	            break;
214	        }
215	
216	        uart_puts("BClk RETRY\r\n");
217	    }
218	
219	    boot_wdt_feed();
220	
221	    if (!cold_ok) {
222	        /* All retries exhausted: DPLL not enabled.  Do NOT jump to app
223	         * (app would see BootROM default state, DPLL off, DVFS would try
224	         * to switch to cksel=2 with DPLL off — undefined behavior).
225	         * Hang with WDT feed: the chip resets in ~8 s, giving a clean
226	         * retry window and leaving UART output visible for debugging. */
227	        uart_puts("BClk RETRY FAIL\r\n");
228	        for (;;) {
229	            boot_wdt_feed();
230	        }
231	    }
232	
233	    /* --- FAL partition parse -> find "app". */
234	
235	    boot_wdt_feed();
236	    app = fal_find("app");
237	    if (app == (const struct fal_partition *)0) {
238	        uart_puts("BAD\r\nno app part\r\n");
239	        for (;;) {
240	            boot_wdt_feed();
241	        }
242	    }
243	    app_vec = FLASH_BASE + (uint32_t)app->offset;
244	    log_u32("partition app @ ", app_vec);
245	
246	    /* --- Validate app header. */
247	
248	    if (!validate_app(app_vec)) {
249	        for (;;) {
250	            boot_wdt_feed();
251	        }
252	    }
253	
254	    /* --- Feed WDT one last time before jumping to app.
255	     * The app's DVFS bring-up runs quickly (< 1 ms), but if it ever hangs
256	     * before the NuttX scheduler takes over WDT management, the hardware
257	     * WDT still fires. */
258	
259	    boot_wdt_feed();

