### WDT Wrapper 示例（按 `wdg_pattern.md`）

```c
// chip/cp/bk7258_cp_wdt.c

#include <nuttx/config.h>
#include <nuttx/timers/watchdog.h>
#include <driver/wdt.h>          // SDK API
#include <driver/aon_wdt.h>     // SDK API

struct bk7258_wdt_lowerhalf_s {
  struct watchdog_lowerhalf_s wdt_lh;
  uint32_t timeout;
  bool started;
};

static int bk7258_wdt_start(struct watchdog_lowerhalf_s *lower) {
  struct bk7258_wdt_lowerhalf_s *priv = (void *)lower;
  if (!bk_wdt_is_driver_inited()) bk_wdt_driver_init();
  return (bk_wdt_start(priv->timeout) == BK_OK) ? OK : -EIO;
}

static int bk7258_wdt_stop(struct watchdog_lowerhalf_s *lower) {
  bk_wdt_stop();
  bk_aon_wdt_stop();  // 关 AON WDT，修根因
  return OK;
}

static int bk7258_wdt_keepalive(struct watchdog_lowerhalf_s *lower) {
  return (bk_wdt_feed() == BK_OK) ? OK : -EIO;
}

static int bk7258_wdt_settimeout(struct watchdog_lowerhalf_s *lower, uint32_t timeout) {
  struct bk7258_wdt_lowerhalf_s *priv = (void *)lower;
  if (timeout == 0) return -EINVAL;
  priv->timeout = (timeout > 0xFFFF) ? 0xFFFF : timeout;
  if (priv->started) bk_wdt_start(priv->timeout);
  return OK;
}

// ... getstatus, ioctl ...

int bk7258_wdt_initialize(void) {
  static bool s_inited;
  if (s_inited) return OK;
  s_inited = true;

  bk_aon_wdt_stop();  // ★根因修复：立刻关 AON WDT
  bk_wdt_driver_init();

  struct bk7258_wdt_lowerhalf_s *priv = &g_bk7258_wdt;
  priv->wdt_lh.ops = &g_bk7258_wdt_ops;
  priv->timeout = 8000;
  priv->started = false;

  void *h = watchdog_register("/dev/watchdog0", &priv->wdt_lh);
  return h ? OK : -ENOMEM;
}
```

### Flash MTD Wrapper 示例

```c
// chip/cp/bk7258_cp_flash_mtd.c

#include <nuttx/mtd/mtd.h>
#include <driver/flash.h>  // SDK API

static ssize_t bk7258_flash_bread(struct mtd_dev_s *dev, off_t startblock,
                                   size_t nblocks, uint8_t *buffer) {
  uint32_t offset = startblock * 4096;
  uint32_t nbytes = nblocks * 4096;
  return (bk_flash_read_bytes(offset, buffer, nbytes) == BK_OK) ? nblocks : -EIO;
}

static int bk7258_flash_erase(struct mtd_dev_s *dev, off_t startblock, size_t nblocks) {
  bk_flash_set_protect_type(FLASH_PROTECT_NONE);
  for (size_t i = 0; i < nblocks; i++) {
    bk_flash_erase_sector((startblock + i) * 4096);
  }
  bk_flash_set_protect_type(FLASH_UNPROTECT_LAST_BLOCK);
  return OK;
}

static ssize_t bk7258_flash_bwrite(struct mtd_dev_s *dev, off_t startblock,
                                    size_t nblocks, const uint8_t *buffer) {
  uint32_t offset = startblock * 4096;
  uint32_t nbytes = nblocks * 4096;
  bk_flash_set_protect_type(FLASH_PROTECT_NONE);
  int ret = bk_flash_write_bytes(offset, buffer, nbytes);
  bk_flash_set_protect_type(FLASH_UNPROTECT_LAST_BLOCK);
  return (ret == BK_OK) ? nblocks : -EIO;
}
```

