/****************************************************************************
 * board/bk7258_t5ai/chip/bk7258_os_adapt.c
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * BK7258 NuttX OS adaptation layer.
 * Bridges SDK prebuilt library (libdriver.a) FreeRTOS API calls to NuttX.
 * Reference: vendor_beken/chips/bk7236n/beken_os_adapt.c
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/kthread.h>
#include <nuttx/mutex.h>
#include <nuttx/semaphore.h>
#include <nuttx/kmalloc.h>
#include <nuttx/clock.h>
#include <nuttx/irq.h>
#include <nuttx/sched.h>
#include <nuttx/signal.h>
#include <nuttx/wdog.h>
#include <string.h>
#include <debug.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define BEKEN_WAIT_FOREVER  0xFFFFFFFFu

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct timer_adpt
{
  struct wdog_s wdog;
  bool          repeat;
  uint32_t      delay;
  void          *priv;
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static inline bk_err_t beken_errno_trans(int ret)
{
  return (ret == 0) ? 0 /* BK_OK */ : -1 /* BK_FAIL */;
}

/****************************************************************************
 * Public Functions - Memory
 ****************************************************************************/

void *os_malloc(unsigned int size)
{
  return kmm_malloc(size);
}

void os_free(void *ptr)
{
  kmm_free(ptr);
}

void *os_calloc(unsigned int nmemb, unsigned int size)
{
  return kmm_calloc(nmemb, size);
}

void *os_realloc(void *ptr, unsigned int size)
{
  return kmm_realloc(ptr, size);
}

void *os_memset(void *s, int c, unsigned int n)
{
  return memset(s, c, n);
}

void *os_memcpy(void *dest, const void *src, unsigned int n)
{
  return memcpy(dest, src, n);
}

int os_memcmp(const void *s1, const void *s2, unsigned int n)
{
  return memcmp(s1, s2, n);
}

char *os_strcpy(char *dest, const char *src)
{
  return strcpy(dest, src);
}

unsigned int os_strlen(const char *s)
{
  return (unsigned int)strlen(s);
}

int os_strncmp(const char *s1, const char *s2, unsigned int n)
{
  return strncmp(s1, s2, n);
}

/****************************************************************************
 * Public Functions - Tick / Time
 ****************************************************************************/

unsigned int bk_get_tick(void)
{
  return (unsigned int)clock_systime_ticks();
}

unsigned int rtos_get_ms_per_tick(void)
{
  return MSEC_PER_TICK;
}

unsigned int rtos_ms_to_tick(unsigned int ms)
{
  return MSEC2TICK(ms);
}

unsigned int bk_ms_to_ticks(unsigned int ms)
{
  return MSEC2TICK(ms);
}

unsigned int bk_ticks_to_ms(unsigned int ticks)
{
  return TICK2MSEC(ticks);
}

/****************************************************************************
 * Public Functions - Interrupt / Critical Section
 ****************************************************************************/

unsigned int GLOBAL_INT_DISABLE(void)
{
  return (unsigned int)irqsave();
}

void GLOBAL_INT_RESTORE(unsigned int flags)
{
  irqrestore((irqstate_t)flags);
}

uint32_t rtos_disable_int(void)
{
  return (uint32_t)enter_critical_section();
}

void rtos_enable_int(uint32_t int_level)
{
  leave_critical_section((irqstate_t)int_level);
}

uint32_t rtos_enter_critical(void)
{
  return (uint32_t)enter_critical_section();
}

void rtos_exit_critical(uint32_t int_level)
{
  leave_critical_section((irqstate_t)int_level);
}

/****************************************************************************
 * Public Functions - Thread
 ****************************************************************************/

bk_err_t rtos_create_thread(void *thread, uint8_t priority,
                            const char *name,
                            void *function, uint32_t stack_size,
                            void *arg)
{
  pid_t pid;

  /* FreeRTOS stack_size is in words (4 bytes each), NuttX uses bytes */

  pid = kthread_create(name, SCHED_PRIORITY_DEFAULT + 2 - priority,
                       stack_size, (main_t)function, (char *const *)arg);
  if (pid <= 0)
    {
      ferr("ERROR: Failed to create thread(%s): %d\n", name, pid);
      return -1;
    }

  if (thread)
    {
      *(void **)thread = (void *)((uintptr_t)pid);
    }

  return 0;
}

bk_err_t rtos_delete_thread(void *thread)
{
  pid_t pid = 0;

  if (thread)
    {
      pid = (pid_t)((uintptr_t)*(void **)thread);
    }

  task_delete(pid);
  return 0;
}

bool rtos_is_current_thread(void *thread)
{
  pid_t pid = nxsched_getpid();
  return (pid == (pid_t)((uintptr_t)*(void **)thread));
}

void *rtos_get_current_thread(void)
{
  return (void *)((uintptr_t)nxsched_getpid());
}

bk_err_t rtos_thread_join(void *thread)
{
  /* Not implemented */
  return 0;
}

bk_err_t rtos_create_sram_thread(void *thread, uint8_t priority,
                                 const char *name,
                                 void *function, uint32_t stack_size,
                                 void *arg)
{
  return rtos_create_thread(thread, priority, name, function,
                            stack_size, arg);
}

/****************************************************************************
 * Public Functions - Semaphore
 ****************************************************************************/

bk_err_t rtos_init_semaphore(void *semaphore, int max_count)
{
  sem_t *sem;
  int ret;

  sem = kmm_malloc(sizeof(sem_t));
  if (!sem)
    {
      ferr("ERROR: Failed to malloc semaphore\n");
      return -1;
    }

  ret = nxsem_init(sem, 0, 0);
  if (ret == OK)
    {
      *(void **)semaphore = sem;
    }
  else
    {
      ferr("ERROR: Failed to create semaphore: %d\n", ret);
      kmm_free(sem);
    }

  return beken_errno_trans(ret);
}

bk_err_t rtos_init_semaphore_ex(void *semaphore, int max_count,
                                int init_count)
{
  sem_t *sem;
  int ret;

  sem = kmm_malloc(sizeof(sem_t));
  if (!sem)
    {
      ferr("ERROR: Failed to malloc semaphore\n");
      return -1;
    }

  ret = nxsem_init(sem, 0, init_count);
  if (ret == OK)
    {
      *(void **)semaphore = sem;
    }
  else
    {
      ferr("ERROR: Failed to create semaphore: %d\n", ret);
      kmm_free(sem);
    }

  return beken_errno_trans(ret);
}

bk_err_t rtos_set_semaphore(void *semaphore)
{
  sem_t *sem = *(void **)semaphore;
  int ret;

  ret = nxsem_post(sem);
  if (ret != OK)
    {
      ferr("ERROR: Failed to post semaphore: %d\n", ret);
    }

  return beken_errno_trans(ret);
}

bk_err_t rtos_get_semaphore(void *semaphore, uint32_t timeout_ms)
{
  sem_t *sem = *(void **)semaphore;
  int ret;

  if (timeout_ms == 0)
    {
      ret = nxsem_trywait(sem);
    }
  else if (timeout_ms == BEKEN_WAIT_FOREVER)
    {
      ret = nxsem_wait(sem);
    }
  else
    {
      ret = nxsem_tickwait(sem, MSEC2TICK(timeout_ms));
    }

  return beken_errno_trans(ret);
}

bk_err_t rtos_deinit_semaphore(void *semaphore)
{
  sem_t *sem = *(void **)semaphore;
  int ret;

  ret = nxsem_destroy(sem);
  kmm_free(sem);

  return beken_errno_trans(ret);
}

/****************************************************************************
 * Public Functions - Mutex
 ****************************************************************************/

bk_err_t rtos_init_mutex(void *mtx)
{
  mutex_t *m;
  int ret;

  m = kmm_malloc(sizeof(mutex_t));
  if (!m)
    {
      ferr("ERROR: Failed to malloc mutex\n");
      return -1;
    }

  ret = nxmutex_init(m);
  if (ret == OK)
    {
      *(void **)mtx = m;
    }
  else
    {
      ferr("ERROR: Failed to create mutex: %d\n", ret);
      kmm_free(m);
    }

  return beken_errno_trans(ret);
}

bk_err_t rtos_mutex_lock(void *mtx)
{
  mutex_t *m = *(void **)mtx;
  return beken_errno_trans(nxmutex_lock(m));
}

bk_err_t rtos_mutex_unlock(void *mtx)
{
  mutex_t *m = *(void **)mtx;
  return beken_errno_trans(nxmutex_unlock(m));
}

bk_err_t rtos_deinit_mutex(void *mtx)
{
  mutex_t *m = *(void **)mtx;
  int ret;

  ret = nxmutex_destroy(m);
  kmm_free(m);

  return beken_errno_trans(ret);
}

/****************************************************************************
 * Public Functions - Delay
 ****************************************************************************/

bk_err_t rtos_delay_milliseconds(unsigned int ms)
{
