664	  if (timeout_ms == BEKEN_WAIT_FOREVER || timeout_ms == 0)
665	    {
666	      ret = file_mq_send(&mq_adpt->mq, (const char *)message,
667	                         mq_adpt->msgsize, 0);
668	      if (ret < 0)
669	        {
670	          wlerr("Failed to send message to mqueue error=%d\n", ret);
671	        }
672	    }
673	  else
674	    {
675	      struct timespec timeout;
676	
677	      clock_gettime(CLOCK_REALTIME, &timeout);
678	      timeout.tv_sec  += timeout_ms / 1000;
679	      timeout.tv_nsec += (timeout_ms % 1000) * 1000 * 1000;
680	
681	      if (timeout.tv_nsec >= 1000000000)
682	        {
683	          timeout.tv_sec  += timeout.tv_nsec / 1000000000;
684	          timeout.tv_nsec %= 1000000000;
685	        }
686	
687	      ret = file_mq_timedsend(&mq_adpt->mq, (const char *)message,
688	                              mq_adpt->msgsize, 0, &timeout);
689	      if (ret < 0)
690	        {
691	          wlerr("Failed to timedsend message to mqueue error=%d\n", ret);
692	        }
693	    }
694	
695	  return beken_errno_trans(ret);
696	}
