1558	u32 rtos_wait_event_ex(rtos_event_ext_t *event, u32 event_flag,
1559	                       u32 any_event, u32 timeout)
1560	{
1561	  sem_t *sem = (sem_t *)event->event_semaphore;
1562	  int ret;
1563	
1564	  if (timeout == BEKEN_WAIT_FOREVER)
1565	    {
1566	      ret = nxsem_wait(sem);
1567	    }
1568	  else if (timeout == 0)
1569	    {
1570	      ret = nxsem_trywait(sem);
1571	    }
1572	  else
1573	    {
1574	      ret = nxsem_tickwait(sem, MSEC2TICK(timeout));
1575	    }
1576	
1577	  if (ret == OK)
1578	    {
1579	      u32 flags = event->event_flag & event_flag;
1580	      event->event_flag &= ~event_flag;
1581	      return flags;
1582	    }
1583	
1584	  return 0;
1585	}
