1	/****************************************************************************
2	 * contest2026_135_yongwangzhiqian/board/bk7258_t5ai/chip/bk7258_flash_mtd.c
3	 *
4	 * SPDX-License-Identifier: Apache-2.0
5	 *
6	 * BK7258 (T5-AI) on-chip flash data-partition MTD lower-half.
7	 *
8	 * Exposes the 1 MiB data partition (logical 0x00100000..0x001FFFFF) as a
9	 * NuttX MTD.  Read/erase/write use the board-verified flash-controller
10	 * sequence:
11	 *
12	 *   wait BUSY clear -> OP_CMD = (addr[23:0] | op<<24) -> set OP_CTRL.OP_SW
13	 *   -> wait BUSY clear -> read DATA_IN / stage DATA_SW_FLASH.
14	 *
15	 * Geometry is fixed for the GD25Q64-class part:
16	 *   blocksize  = 4096  (read/write block unit)
17	 *   erasesize  = 4096  (sector erase unit, a multiple of blocksize)
18	 *   neraseblocks = 256 (1 MiB / 4 KiB)
19	 ****************************************************************************/
20	
21	/****************************************************************************
22	 * Included Files
23	 ****************************************************************************/
24	
25	#include <nuttx/config.h>
26	
27	#include <stdint.h>
28	#include <string.h>
29	#include <errno.h>
30	#include <debug.h>
31	
32	#include <nuttx/mtd/mtd.h>
33	
34	#include "bk7258_flash_mtd.h"
35	
36	/****************************************************************************
37	 * Pre-processor Definitions
38	 ****************************************************************************/
39	
40	/* Flash controller MMIO (Armino SOC_FLASH_REG_BASE = 0x44030000). */
41	
42	#define BK7258_FREG(a)              (*(volatile uint32_t *)(a))
43	
44	#define BK7258_FLASH_BASE           0x44030000u
45	#define BK7258_FLASH_OP_CTRL        (BK7258_FLASH_BASE + 0x10u)
46	#define BK7258_FLASH_DATA_SW_FLASH  (BK7258_FLASH_BASE + 0x14u)
47	#define BK7258_FLASH_DATA_IN        (BK7258_FLASH_BASE + 0x18u)
48	#define BK7258_FLASH_CMD_CFG        (BK7258_FLASH_BASE + 0x1cu)
49	#define BK7258_FLASH_RD_ID          (BK7258_FLASH_BASE + 0x20u)
50	#define BK7258_FLASH_STATE         (BK7258_FLASH_BASE + 0x24u)
51	#define BK7258_FLASH_CONF          (BK7258_FLASH_BASE + 0x28u)
52	#define BK7258_FLASH_OP_CMD         (BK7258_FLASH_BASE + 0x54u)
53	
54	#define BK7258_FLASH_BUSY_BIT       (1u << 31)
55	#define BK7258_FLASH_OP_SW_BIT      (1u << 29)
56	#define BK7258_FLASH_WP_VALUE_BIT   (1u << 30)
57	
58	#define BK7258_FLASH_OP_CMD_WREN   1u
59	#define BK7258_FLASH_OP_CMD_RDSR   3u
60	#define BK7258_FLASH_OP_CMD_WRSR   4u
61	#define BK7258_FLASH_OP_CMD_READ   5u
62	#define BK7258_FLASH_OP_CMD_PP     12u
63	#define BK7258_FLASH_OP_CMD_SE     13u
64	#define BK7258_FLASH_OP_CMD_RDID   20u
65	
66	/* SR0 block-protect bits (GD25Q64-class): BP0/BP1/BP2/TB/SEC/CMP at
67	 * bits 2..6.  The default SR0=0x1c observed on this board protects a range
68	 * that includes the boot/app region; writes only succeed while these are
69	 * cleared.  WIP(bit0)/WEL(bit1) are runtime, never written here.
70	 */
71	
72	#define BK7258_FLASH_SR_PROTECT_MASK 0x7cu
73	#define BK7258_FLASH_WRSR_DATA_SHIFT 10u
74	#define BK7258_FLASH_WRSR_DATA_MASK  (0xffffu << BK7258_FLASH_WRSR_DATA_SHIFT)
75	
76	/* Verified data partition layout (matches docs n5-flash-filesystem.md). */
77	
78	#define BK7258_DATA_PART_BASE       0x00100000u
79	#define BK7258_DATA_PART_SIZE       0x00100000u
80	
81	#define BK7258_FLASH_BLOCK_SIZE     4096u
82	#define BK7258_FLASH_ERASE_SIZE     4096u
83	#define BK7258_FLASH_NBLOCKS        (BK7258_DATA_PART_SIZE / BK7258_FLASH_BLOCK_SIZE)
84	
85	#define BK7258_FLASH_TIMEOUT        1000000u
86	
87	/****************************************************************************
88	 * Private Types
89	 ****************************************************************************/
90	
91	struct bk7258_flash_mtd_s
92	{
93	  struct mtd_dev_s mtd;           /* External MTD interface */
94	};
95	
96	/****************************************************************************
97	 * Private Data
98	 ****************************************************************************/
99	
100	static struct bk7258_flash_mtd_s g_bk7258_flash_mtd;
101	
102	/****************************************************************************
103	 * Private Helpers
104	 ****************************************************************************/
105	
106	static inline int bk7258_flash_wait_ready(void)
107	{
108	  uint32_t timeout = BK7258_FLASH_TIMEOUT;
109	
110	  while ((BK7258_FREG(BK7258_FLASH_OP_CTRL) & BK7258_FLASH_BUSY_BIT) != 0)
111	    {
112	      if (--timeout == 0)
113	        {
114	          return -ETIMEDOUT;
115	        }
116	    }
117	
118	  return OK;
119	}
120	
121	/* Read 16 bytes (4 words) from an absolute flash address using the proven
122	 * READ op sequence.  Returns OK/-errno.  Only valid at 0x20-aligned addresses
123	 * (the controller READ is a 32-byte burst).  Retained as a utility; not all
124	 * configurations reference it from outside the driver.
125	 */
126	
127	static int __attribute__((unused)) bk7258_flash_read16(uint32_t addr,
128	                                                       uint32_t out[4])
129	{
130	  uint32_t ctrl;
131	  unsigned int i;
132	
133	  if (bk7258_flash_wait_ready() < 0)
134	    {
135	      return -ETIMEDOUT;
136	    }
137	
138	  /* op_cmd: addr[23:0] | (op_type_sw << 24), READ = 5. */
139	
140	  BK7258_FREG(BK7258_FLASH_OP_CMD) =
141	      (addr & 0x00ffffffu) | (BK7258_FLASH_OP_CMD_READ << 24);
142	
143	  ctrl = BK7258_FREG(BK7258_FLASH_OP_CTRL);
144	  BK7258_FREG(BK7258_FLASH_OP_CTRL) = ctrl | BK7258_FLASH_OP_SW_BIT;
145	
146	  if (bk7258_flash_wait_ready() < 0)
147	    {
148	      return -ETIMEDOUT;
149	    }
150	
151	  for (i = 0; i < 4; i++)
152	    {
153	      out[i] = BK7258_FREG(BK7258_FLASH_DATA_IN);
154	    }
155	
156	  return OK;
157	}
158	
159	/* Read 32 bytes (8 words) from a 0x20-aligned flash address.  This is the
160	 * SDK-proven READ granularity (flash_read_data: 8 words per op, addr += 32);
161	 * the controller READ is a 32-byte burst, so reads at non-0x20-aligned
162	 * addresses return wrong data.  bread uses this exclusively.
163	 */
164	
165	static int bk7258_flash_read32(uint32_t addr, uint32_t out[8])
166	{
167	  uint32_t ctrl;
168	  unsigned int i;
169	
170	  if (bk7258_flash_wait_ready() < 0)
171	    {
172	      return -ETIMEDOUT;
173	    }
174	
175	  BK7258_FREG(BK7258_FLASH_OP_CMD) =
176	      (addr & 0x00ffffffu) | (BK7258_FLASH_OP_CMD_READ << 24);
177	
178	  ctrl = BK7258_FREG(BK7258_FLASH_OP_CTRL);
179	  BK7258_FREG(BK7258_FLASH_OP_CTRL) = ctrl | BK7258_FLASH_OP_SW_BIT;
180	
181	  if (bk7258_flash_wait_ready() < 0)
182	    {
183	      return -ETIMEDOUT;
184	    }
185	
186	  for (i = 0; i < 8; i++)
187	    {
188	      out[i] = BK7258_FREG(BK7258_FLASH_DATA_IN);
189	    }
190	
191	  return OK;
192	}
193	
194	static uint32_t bk7258_flash_read_id(void)
195	{
196	  uint32_t ctrl;
197	
198	  if (bk7258_flash_wait_ready() < 0)
199	    {
200	      return 0;
201	    }
202	
203	  BK7258_FREG(BK7258_FLASH_OP_CMD) =
204	      (uint32_t)BK7258_FLASH_OP_CMD_RDID << 24;
205	
206	  ctrl = BK7258_FREG(BK7258_FLASH_OP_CTRL);
207	  BK7258_FREG(BK7258_FLASH_OP_CTRL) = ctrl | BK7258_FLASH_OP_SW_BIT;
208	
209	  if (bk7258_flash_wait_ready() < 0)
210	    {
211	      return 0;
212	    }
213	
214	  return BK7258_FREG(BK7258_FLASH_RD_ID);
215	}
216	
217	/* Trigger a flash controller op at `addr` with op-type `op`, without touching
218	 * the WP_VALUE bit.  This is the sequence N5-D5 board-verified for READ/SE/PP
219	 * after SR0 protection has been cleared.
220	 */
221	
222	static int bk7258_flash_swop(uint32_t addr, uint32_t op)
223	{
224	  uint32_t ctrl;
225	
226	  if (bk7258_flash_wait_ready() < 0)
227	    {
228	      return -ETIMEDOUT;
229	    }
230	
231	  BK7258_FREG(BK7258_FLASH_OP_CMD) =
232	      (addr & 0x00ffffffu) | (op << 24);
233	
234	  ctrl = BK7258_FREG(BK7258_FLASH_OP_CTRL);
235	  BK7258_FREG(BK7258_FLASH_OP_CTRL) = ctrl | BK7258_FLASH_OP_SW_BIT;
236	
237	  return bk7258_flash_wait_ready();
238	}
239	
240	static int bk7258_flash_wren(void)
241	{
242	  return bk7258_flash_swop(0u, BK7258_FLASH_OP_CMD_WREN);
243	}
244	
245	static uint32_t bk7258_flash_read_sr(void)
246	{
247	  if (bk7258_flash_swop(0u, BK7258_FLASH_OP_CMD_RDSR) < 0)
248	    {
249	      return 0xffffffffu;
250	    }
251	
252	  return BK7258_FREG(BK7258_FLASH_STATE) & 0xffu;
253	}
254	
255	/* WRSR uses FLASH_CONF.wrsr_data[10:25] as the payload and needs WP_VALUE set
256	 * for the op (N5-D5 board-verified sequence).
257	 */
258	
259	static int bk7258_flash_write_sr(uint8_t sr)
260	{
261	  uint32_t conf0;
262	  uint32_t conf;
263	  uint32_t ctrl;
264	  int ret;
265	
266	  if (bk7258_flash_wren() < 0)
267	    {
268	      return -ETIMEDOUT;
269	    }
270	
271	  BK7258_FREG(BK7258_FLASH_CMD_CFG) = 0u;
272	
273	  conf0 = BK7258_FREG(BK7258_FLASH_CONF);
274	  conf = (conf0 & ~BK7258_FLASH_WRSR_DATA_MASK) |
275	         ((uint32_t)sr << BK7258_FLASH_WRSR_DATA_SHIFT);
276	  BK7258_FREG(BK7258_FLASH_CONF) = conf;
277	
278	  if (bk7258_flash_wait_ready() < 0)
279	    {
280	      BK7258_FREG(BK7258_FLASH_CONF) = conf0;
281	      return -ETIMEDOUT;
282	    }
283	
284	  BK7258_FREG(BK7258_FLASH_OP_CMD) = (uint32_t)BK7258_FLASH_OP_CMD_WRSR << 24;
285	
286	  ctrl = BK7258_FREG(BK7258_FLASH_OP_CTRL);
287	  BK7258_FREG(BK7258_FLASH_OP_CTRL) =
288	      ctrl | BK7258_FLASH_OP_SW_BIT | BK7258_FLASH_WP_VALUE_BIT;
289	
290	  ret = bk7258_flash_wait_ready();
291	
292	  BK7258_FREG(BK7258_FLASH_OP_CTRL) =
293	      BK7258_FREG(BK7258_FLASH_OP_CTRL) & ~BK7258_FLASH_WP_VALUE_BIT;
294	  BK7258_FREG(BK7258_FLASH_CONF) = conf0;
295	
296	  return ret;
297	}
298	
299	/* N5-D6-B protection policy (option A): clear SR0 block-protect bits around
300	 * each erase/write call and restore the original value afterwards, so the
301	 * boot/app region keeps its hardware protection outside the op window.
302	 *
303	 * Returns: 1 if protection was changed (caller must restore), 0 if already
304	 * clear, negative errno on failure.
305	 */
306	
307	static int bk7258_flash_unprotect(uint8_t *saved_sr)
308	{
309	  uint32_t sr;
310	  int ret;
311	
312	  sr = bk7258_flash_read_sr();
313	  if (sr == 0xffffffffu)
314	    {
315	      _err("bk7258_flash_unprotect: SR0 read failed\n");
316	      return -EIO;
317	    }
318	
319	  *saved_sr = (uint8_t)sr;
320	
321	  if ((sr & BK7258_FLASH_SR_PROTECT_MASK) == 0u)
322	    {
323	      return 0;
324	    }
325	
326	  ret = bk7258_flash_write_sr((uint8_t)(sr & ~BK7258_FLASH_SR_PROTECT_MASK));
327	  if (ret < 0)
328	    {
329	      /* Best-effort restore of the original SR0; ignore the return value
330	       * since we are already on the failure path.
331	       */
332	
333	      (void)bk7258_flash_write_sr((uint8_t)sr);
334	      _err("bk7258_flash_unprotect: clear SR0 protect failed (ret=%d)\n", ret);
335	      return ret;
336	    }
337	
338	  if ((bk7258_flash_read_sr() & BK7258_FLASH_SR_PROTECT_MASK) != 0u)
339	    {
340	      (void)bk7258_flash_write_sr((uint8_t)sr);
341	      _err("bk7258_flash_unprotect: SR0 protect bits still set after clear\n");
342	      return -EIO;
343	    }
344	
345	  return 1;
346	}
347	
348	static int bk7258_flash_restore(uint8_t saved_sr, int changed)
349	{
350	  if (changed)
351	    {
352	      int ret;
353	
354	      /* Restore only the writable protect bits; leave WIP/WEL untouched. */
355	
356	      ret = bk7258_flash_write_sr((uint8_t)(saved_sr & 0xfcu));
357	      if (ret < 0)
358	        {
359	          _err("bk7258_flash_restore: SR0 restore failed (ret=%d); "
360	               "boot/app region may be unprotected\n", ret);
361	        }
362	
363	      return ret;
364	    }
365	
366	  return OK;
367	}
368	
369	/* Program one 32-byte chunk (8 words) at `addr` using the N5-D5 board-verified
370	 * PP sequence: WREN -> stage 8 words to DATA_SW_FLASH -> PP.  Caller must have
371	 * already cleared SR0 protection for the call.
372	 */
373	
374	static int bk7258_flash_program32(uint32_t addr, FAR const uint8_t *buf)
375	{
376	  unsigned int i;
377	
378	  if (bk7258_flash_wren() < 0)
379	    {
380	      return -ETIMEDOUT;
381	    }
382	
383	  for (i = 0; i < 8; i++)
384	    {
385	      uint32_t w = (uint32_t)buf[0] | ((uint32_t)buf[1] << 8) |
386	                   ((uint32_t)buf[2] << 16) | ((uint32_t)buf[3] << 24);
387	
388	      BK7258_FREG(BK7258_FLASH_DATA_SW_FLASH) = w;
389	      buf += 4;
390	    }
391	
392	  return bk7258_flash_swop(addr, BK7258_FLASH_OP_CMD_PP);
393	}
394	
395	/****************************************************************************
396	 * MTD Methods
397	 ****************************************************************************/
398	
399	/* Read whole 4 KiB blocks.  startblock/nblocks are in block units; each block
400	 * is read 32 bytes at a time from 0x20-aligned addresses (the controller READ
401	 * is a 32-byte burst, so mid-burst offsets return wrong data).
402	 */
403	
404	static ssize_t bk7258_flash_bread(FAR struct mtd_dev_s *dev, off_t startblock,
405	                                  size_t nblocks, FAR uint8_t *buffer)
406	{
407	  size_t block;
408	  size_t off;
409	  uint32_t addr;
410	  uint32_t wbuf[8];
411	  FAR uint8_t *p;
412	
413	  (void)dev;
414	
415	  if (startblock < 0 || (size_t)startblock + nblocks > BK7258_FLASH_NBLOCKS)
416	    {
417	      return -EINVAL;
418	    }
419	
420	  p = buffer;
421	
422	  for (block = 0; block < nblocks; block++)
423	    {
424	      addr = BK7258_DATA_PART_BASE +
425	             ((size_t)startblock + block) * BK7258_FLASH_BLOCK_SIZE;
426	
427	      for (off = 0; off < BK7258_FLASH_BLOCK_SIZE; off += 32u)
428	        {
429	          unsigned int i;
430	
431	          if (bk7258_flash_read32(addr + off, wbuf) < 0)
432	            {
433	              return -EIO;
434	            }
435	
436	          for (i = 0; i < 8; i++)
437	            {
438	              FAR uint8_t *wp = (FAR uint8_t *)&wbuf[i];
439	              unsigned int b;
440	
441	              for (b = 0; b < 4; b++)
442	                {
443	                  *p++ = wp[b];
444	                }
445	            }
446	        }
447	    }
448	
449	  return nblocks;
450	}
451	
452	/* Erase whole 4 KiB sectors.  SR0 protection is cleared once at entry and
453	 * restored at exit (N5-D6-B option A); each sector uses the verified
454	 * swop(addr, SE) sequence.
455	 */
456	
457	static int bk7258_flash_erase(FAR struct mtd_dev_s *dev, off_t startblock,
458	                              size_t nblocks)
459	{
460	  uint8_t saved_sr;
461	  size_t block;
462	  int changed;
463	
464	  (void)dev;
465	
466	  if (startblock < 0 || (size_t)startblock + nblocks > BK7258_FLASH_NBLOCKS)
467	    {
468	      return -EINVAL;
469	    }
470	
471	  changed = bk7258_flash_unprotect(&saved_sr);
472	  if (changed < 0)
473	    {
474	      return changed;
475	    }
476	
477	  for (block = 0; block < nblocks; block++)
478	    {
479	      uint32_t addr = BK7258_DATA_PART_BASE +
480	                      ((size_t)startblock + block) * BK7258_FLASH_BLOCK_SIZE;
481	
482	      if (bk7258_flash_swop(addr, BK7258_FLASH_OP_CMD_SE) < 0)
483	        {
484	          /* Op failed: best-effort restore, then report the failure. */
485	
486	          (void)bk7258_flash_restore(saved_sr, changed > 0);
487	          return -EIO;
488	        }
489	    }
490	
491	  /* Op succeeded: data is committed.  A restore failure here must not turn
492	   * a successful erase into a failure (the sectors are already erased), so
493	   * the restore return value is intentionally ignored.
494	   */
495	
496	  (void)bk7258_flash_restore(saved_sr, changed > 0);
497	  return OK;
498	}
499	
500	/* Write whole 4 KiB blocks.  Programs 32 bytes at a time via the verified PP
501	 * sequence (WREN -> 8 words -> PP), SR0 protection cleared/restored around
502	 * the whole call.  The caller (filesystem layer) is responsible for erasing
503	 * the block first; programming only flips bits 1->0.
504	 */
505	
506	static ssize_t bk7258_flash_bwrite(FAR struct mtd_dev_s *dev, off_t startblock,
507	                                   size_t nblocks, FAR const uint8_t *buffer)
508	{
509	  uint8_t saved_sr;
510	  size_t block;
511	  size_t off;
512	  int changed;
513	
514	  (void)dev;
515	
516	  if (startblock < 0 || (size_t)startblock + nblocks > BK7258_FLASH_NBLOCKS)
517	    {
518	      return -EINVAL;
519	    }
520	
521	  changed = bk7258_flash_unprotect(&saved_sr);
522	  if (changed < 0)
523	    {
524	      return changed;
525	    }
526	
527	  for (block = 0; block < nblocks; block++)
528	    {
529	      uint32_t base = BK7258_DATA_PART_BASE +
530	                      ((size_t)startblock + block) * BK7258_FLASH_BLOCK_SIZE;
531	      FAR const uint8_t *p = buffer + block * BK7258_FLASH_BLOCK_SIZE;
532	
533	      for (off = 0; off < BK7258_FLASH_BLOCK_SIZE; off += 32u)
534	        {
535	          if (bk7258_flash_program32(base + off, p + off) < 0)
536	            {
537	              /* Op failed: best-effort restore, then report the failure. */
538	
539	              (void)bk7258_flash_restore(saved_sr, changed > 0);
540	              return -EIO;
541	            }
542	        }
543	    }
544	
545	  /* Op succeeded: data is committed.  A restore failure here must not turn
546	   * a successful write into a failure (data is already on flash), so the
547	   * restore return value is intentionally ignored.
548	   */
549	
550	  (void)bk7258_flash_restore(saved_sr, changed > 0);
551	  return nblocks;
552	}
553	
554	static int bk7258_flash_ioctl(FAR struct mtd_dev_s *dev, int cmd,
555	                              unsigned long arg)
556	{
557	  switch (cmd)
558	    {
559	      case MTDIOC_GEOMETRY:
560	        {
561	          FAR struct mtd_geometry_s *geo =
562	              (FAR struct mtd_geometry_s *)arg;
563	
564	          if (geo == NULL)
565	            {
566	              return -EINVAL;
567	            }
568	
